UPDATE second_hand_mall
category_id = #{categoryId}, title = #{title}, description = #{description}, content = #{content}, price = #{price}, price_ago = #{priceAgo}, inventory = #{inventory}, status = #{status}, cover_img = #{coverImg}, img_1 = #{img1}, img_2 = #{img2}, img_3 = #{img3}, img_4 = #{img4}, img_5 = #{img5}, remarks = #{remarks}, update_time = NOW()
